repro:
cd /Users/steves/Steves_Files/Work/Research_and_Papers/ctx
.venv/bin/python - <<'EOF'
import re, pathlib
kept = {"ctx","ctx-init","ctx-scan-repo","ctx-source-registry","ctx-telemetry-export","ctx-telemetry-retention","ctx-mcp-server"}
pat = re.compile(r'^\s*(?:\$\s*)?(ctx-[a-z0-9-]+)\s')
hits=[]
for p in sorted(pathlib.Path('.').glob('docs/**/*.md')) + [pathlib.Path('README.md')]:
    infence=False
    for i,line in enumerate(p.read_text(encoding='utf-8').splitlines(),1):
        if line.strip().startswith('```'):
            infence = not infence; continue
        if not infence: continue
        m = pat.match(line)
        if m and m.group(1) not in kept:
            hits.append((str(p), i, line.strip()))
for f,i,l in hits[:10]: print(f"{f}:{i}: {l}")
print("TOTAL:", len(hits))
EOF
sed -n '1,14p' docs/dashboard.md
export PATH="$PWD/.venv/bin:$PATH"; command -v ctx-monitor || echo 'ctx-monitor: command not found'
